// Real pitch-detection engine fed through Chromium's fake microphone with WAV fixtures
// (tests/fixtures, generated by `npm run make-wavs`; expected notes in manifest.json).
import {
  closeSettings,
  containsRun,
  displayedCents,
  displayedNote,
  expect,
  openSettings,
  recordedNotes,
  recordedStatuses,
  recordNotes,
  startTuner,
  test,
  tuner,
} from './helpers';

const DETECT_TIMEOUT = 10_000;

test.describe('sine A4 440 Hz', () => {
  test.use({ wav: 'sine-a4-440.wav' });

  test('shows A4 with ~0 cents and the in-tune state', async ({ page }) => {
    await startTuner(page);
    await expect.poll(() => displayedNote(page), { timeout: DETECT_TIMEOUT }).toBe('A4');
    await expect.poll(() => displayedCents(page)).toBe(0);
    await expect(page.locator('#hint-text')).toHaveText('In tune ✓');
    await expect(tuner(page)).toHaveAttribute('data-status', 'detected');
    await expect(tuner(page)).toHaveAttribute('data-zone', 'in');
    await expect(tuner(page)).toHaveAttribute('data-locked', 'true');
    await expect(page.locator('#hz-target')).toHaveText('440.0 Hz');
    await expect(page.locator('#hz-detected')).toHaveText(/^4(39\.[89]|40\.[012]) Hz$/);
  });

  test('pause releases the mic and clears the reading; resume detects again', async ({ page }) => {
    // Track every mic stream the app opens, to verify pause really releases the microphone.
    await page.addInitScript(() => {
      const w = window as unknown as { __streams: MediaStream[] };
      w.__streams = [];
      const gum = navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices);
      navigator.mediaDevices.getUserMedia = async (c) => {
        const s = await gum(c);
        w.__streams.push(s);
        return s;
      };
    });
    const liveTracks = () =>
      page.evaluate(() =>
        (window as unknown as { __streams: MediaStream[] }).__streams
          .flatMap((s) => s.getTracks())
          .filter((t) => t.readyState === 'live').length,
      );
    await startTuner(page);
    await expect.poll(() => displayedNote(page), { timeout: DETECT_TIMEOUT }).toBe('A4');
    expect(await liveTracks()).toBe(1);

    await page.getByRole('button', { name: 'Pause' }).click();
    await expect(page.locator('#paused')).toBeVisible();
    await expect(page.locator('#paused')).toContainText('Tuner paused');
    await expect.poll(() => displayedNote(page)).toBe('');
    await expect(page.locator('#cents')).toHaveText('Listening…');
    await expect.poll(liveTracks, { message: 'mic released while paused' }).toBe(0);

    await page.getByRole('button', { name: 'Resume' }).click();
    await expect(page.locator('#paused')).toBeHidden();
    await expect.poll(() => displayedNote(page), { timeout: DETECT_TIMEOUT }).toBe('A4');
    await expect(page.getByRole('button', { name: 'Pause' })).toBeVisible();
    expect(await liveTracks()).toBe(1);
  });
});

test.describe('input health (real engine)', () => {
  test.use({ wav: 'sine-a4-440.wav' });

  // Capture the app's AudioContexts and mic streams so the tests can interfere with them.
  test.beforeEach(async ({ page }) => {
    await page.addInitScript(() => {
      const w = window as unknown as { __ctxs: AudioContext[]; __streams: MediaStream[] };
      w.__ctxs = [];
      w.__streams = [];
      const AC = window.AudioContext;
      window.AudioContext = class extends AC {
        constructor(o?: AudioContextOptions) {
          super(o);
          w.__ctxs.push(this);
        }
      };
      const gum = navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices);
      navigator.mediaDevices.getUserMedia = async (c) => {
        const st = await gum(c);
        w.__streams.push(st);
        return st;
      };
    });
  });

  test('mic track ending (unplugged / revoked) → reading cleared, "Microphone stopped" with Resume', async ({ page }) => {
    await startTuner(page);
    await expect.poll(() => displayedNote(page), { timeout: DETECT_TIMEOUT }).toBe('A4');
    await page.evaluate(() => {
      for (const t of (window as unknown as { __streams: MediaStream[] }).__streams.flatMap((s) => s.getTracks())) {
        t.stop(); // stop() alone fires no event; the UA fires 'ended' when a device goes away
        t.dispatchEvent(new Event('ended'));
      }
    });
    await expect(page.locator('#paused')).toBeVisible();
    await expect(page.locator('#paused')).toContainText('Microphone stopped');
    await expect.poll(() => displayedNote(page)).toBe('');
    await page.getByRole('button', { name: 'Resume' }).click();
    await expect(page.locator('#paused')).toBeHidden();
    await expect.poll(() => displayedNote(page), { timeout: DETECT_TIMEOUT }).toBe('A4');
  });

  test('suspended AudioContext → no stale re-analysis; "Listening paused" card resumes it in the tap', async ({ page }) => {
    await startTuner(page);
    await expect.poll(() => displayedNote(page), { timeout: DETECT_TIMEOUT }).toBe('A4');
    // Like iOS after an interruption: the context is suspended and resume() without a user
    // gesture does nothing (Chromium would auto-resume, which the engine also tries).
    await page.evaluate(async () => {
      const ctx = (window as unknown as { __ctxs: AudioContext[] }).__ctxs.at(-1)!;
      ctx.resume = () => Promise.resolve();
      await ctx.suspend();
    });
    await expect(page.locator('#paused')).toBeVisible();
    await expect(page.locator('#paused')).toContainText('Listening paused');
    // Holding → listening instead of re-detecting the frozen buffer forever.
    await expect(tuner(page)).toHaveAttribute('data-status', 'listening', { timeout: 4_000 });
    await page.evaluate(() => {
      const ctx = (window as unknown as { __ctxs: AudioContext[] }).__ctxs.at(-1)!;
      delete (ctx as unknown as { resume?: unknown }).resume; // a real tap can resume again
    });
    await page.getByRole('button', { name: 'Resume' }).click();
    await expect(page.locator('#paused')).toBeHidden();
    await expect.poll(() => displayedNote(page), { timeout: DETECT_TIMEOUT }).toBe('A4');
  });

  test('mic track muted by the system → "in use by another app" hint, no stale reading', async ({ page }) => {
    await startTuner(page);
    await expect.poll(() => displayedNote(page), { timeout: DETECT_TIMEOUT }).toBe('A4');
    await page.evaluate(() => {
      for (const t of (window as unknown as { __streams: MediaStream[] }).__streams.flatMap((s) => s.getTracks())) {
        Object.defineProperty(t, 'muted', { configurable: true, get: () => true });
      }
    });
    await expect(page.locator('#hint-text')).toHaveText('The microphone is in use by another app', { timeout: 4_000 });
    await expect.poll(() => displayedNote(page)).toBe('');
  });
});

test.describe('sine 442 Hz (A4 +7.85¢)', () => {
  test.use({ wav: 'sine-a4-442.wav' });

  test('shows A4 at about +8¢ with the "too high" hint', async ({ page }) => {
    await startTuner(page);
    await expect.poll(() => displayedNote(page), { timeout: DETECT_TIMEOUT }).toBe('A4');
    await expect.poll(() => displayedCents(page)).toBe(8);
    await expect(page.locator('#hint-text')).toHaveText('Too high — tune down ↓');
    await expect(tuner(page)).toHaveAttribute('data-zone', 'close');
    await expect(tuner(page)).toHaveAttribute('data-locked', 'false');
  });

  test('A4 = 442 Hz re-centres the reading to ~0¢; number naming; both persist after reload', async ({ page }) => {
    await startTuner(page);
    await expect.poll(() => displayedCents(page), { timeout: DETECT_TIMEOUT }).toBe(8);

    await openSettings(page);
    await page.locator('#a4-inc').click();
    await page.locator('#a4-inc').click();
    await expect(page.locator('#a4-value')).toHaveText('442 Hz');
    await page.getByRole('radio', { name: '1 2 3' }).check();
    await closeSettings(page);

    await expect(page.locator('#a4-chip')).toHaveText('A4 = 442 Hz');
    await expect.poll(() => displayedCents(page)).toBe(0);
    await expect(page.locator('#hint-text')).toHaveText('In tune ✓');
    await expect(page.locator('#hz-target')).toHaveText('442.0 Hz');
    // Number notation: A = 6, octave 4 → no dots.
    await expect(tuner(page)).toHaveAttribute('data-naming', 'number');
    await expect.poll(() => displayedNote(page)).toBe('6');

    // Persisted: survives a reload.
    await page.reload();
    await page.locator('#btn-start').click();
    await expect(page.locator('#a4-chip')).toHaveText('A4 = 442 Hz');
    await expect.poll(() => displayedNote(page), { timeout: DETECT_TIMEOUT }).toBe('6');
    await expect(tuner(page)).toHaveAttribute('data-naming', 'number');
    await expect.poll(() => displayedCents(page)).toBe(0);
    await openSettings(page);
    await expect(page.locator('#a4-value')).toHaveText('442 Hz');
    await expect(page.getByRole('radio', { name: '1 2 3' })).toBeChecked();
  });
});

for (const { wav, note } of [
  { wav: 'kalimba-c4.wav', note: 'C4' },
  { wav: 'kalimba-e6.wav', note: 'E6' },
]) {
  test.describe(`kalimba pluck ${note}`, () => {
    test.use({ wav });

    test(`shows ${note} (correct octave) within ±3¢`, async ({ page }) => {
      await startTuner(page);
      await recordNotes(page);
      await expect.poll(() => displayedNote(page), { timeout: DETECT_TIMEOUT }).toBe(note);
      const cents = await displayedCents(page);
      expect(cents).not.toBeNull();
      expect(Math.abs(cents!)).toBeLessThanOrEqual(3);
      // The fixture loops (pluck, decay, 3 s of silence): wait for the decay → holding →
      // listening (the hold expires in the silent tail) → next pluck cycle. The held reading
      // keeps the note, and no wrong note/octave ever shows.
      await expect
        .poll(async () => containsRun(await recordedStatuses(page), ['detected', 'holding', 'listening', 'detected']), {
          timeout: 15_000,
          message: 'decay → holding → listening → re-detected',
        })
        .toBe(true);
      expect(await recordedNotes(page)).toEqual([note]);
    });
  });
}

test.describe('kalimba sequence C4 → E4 → G4', () => {
  test.use({ wav: 'kalimba-sequence-c4-e4-g4.wav' });

  test('displayed note follows the plucked notes in order', async ({ page }) => {
    await startTuner(page);
    await recordNotes(page);
    // The fixture loops (8.3 s), so the run may start mid-sequence: look for C4, E4, G4 in a row.
    await expect
      .poll(async () => containsRun(await recordedNotes(page), ['C4', 'E4', 'G4']), {
        timeout: 15_000,
        message: 'notes C4, E4, G4 shown in order',
      })
      .toBe(true);
    const seen = await recordedNotes(page);
    expect(seen.filter((n) => !['C4', 'E4', 'G4'].includes(n)), `unexpected notes in ${seen.join(' ')}`).toEqual([]);
  });
});
